from __future__ import annotations

import json
from collections import Counter
from pathlib import Path

from .research import ProcurementResearch
from .strategy import OfferPlanner


def _traces(location):
    path = Path(location).expanduser()
    candidates = [path] if path.is_file() else sorted(path.rglob("*.json"))
    traces = []
    for candidate in candidates:
        try:
            trace = json.loads(candidate.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if trace.get("format_version") == 1:
            traces.append((candidate, trace))
    return traces


def _choice(proposal):
    message = proposal.get("message") or {}
    return {
        "supplier_id": proposal.get("supplier_id"),
        "action": message.get("action"),
        "term_sheets": message.get("term_sheets", []),
    }


class _ReplayWriter:
    @staticmethod
    def draft(*_args):
        return ""


def summarize(location, replay=False):
    traces = _traces(location)
    score_values, rounds, failures = [], [], Counter()
    deals = completed = 0
    cases, divergences = [], []
    planner = OfferPlanner(ProcurementResearch(None)) if replay else None

    for path, trace in traces:
        result = trace.get("result") or {}
        complete = trace.get("status") == "complete"
        completed += complete
        deals += bool(result.get("deal"))
        score = result.get("score")
        if isinstance(score, (int, float)) and not isinstance(score, bool):
            score_values.append(float(score))
        rounds.append(len(trace.get("decisions", [])))
        if trace.get("error"):
            failures[trace["error"].get("type", "unknown")] += 1
        if result.get("must_haves_ok") is False:
            failures["must_have_violation"] += 1
        cases.append({
            "file": str(path), "case_id": trace.get("case_id"),
            "status": trace.get("status"), "deal": result.get("deal"),
            "score": score, "rounds": len(trace.get("decisions", [])),
            "end_reason": result.get("end_reason"),
        })

        if planner is None:
            continue
        for index, turn in enumerate(trace.get("decisions", [])):
            case, threads = trace.get("case"), turn.get("threads")
            research, proposal = turn.get("research"), turn.get("proposal")
            if not all((case, threads is not None, research is not None, proposal)):
                continue
            if turn.get("mode") == "deadline":
                new = planner.close_decision(case, threads, research)
            else:
                new = planner.decide(case, threads, research, _ReplayWriter())
            if _choice(new) != _choice(proposal):
                divergences.append({
                    "file": str(path), "turn": index,
                    "recorded": _choice(proposal), "current": _choice(new),
                })

    summary = {
        "trace_count": len(traces), "completed_count": completed,
        "deal_rate": deals / completed if completed else None,
        "mean_score": sum(score_values) / len(score_values) if score_values else None,
        "scored_count": len(score_values),
        "mean_decisions": sum(rounds) / len(rounds) if rounds else None,
        "failure_counts": dict(failures), "cases": cases,
    }
    if replay:
        summary["decision_divergences"] = divergences
        summary["divergence_count"] = len(divergences)
        summary["replay_note"] = "Decision comparison only; supplier responses and scores are not simulated."
    return summary

    def offer_packages(self, case, threads, sid, research):
        """Create the current BATNA-safe package set without drafting email prose."""
        events = threads[sid]
        if moves_left(case, events) <= 0 or latest(events).get("status") in {"final_offer", "agreed"}:
            return []
        state = self._state(case, sid, events, research)
        standard = state["standard"]
        cap = self.batna(case, {other: messages for other, messages in threads.items() if other != sid}, sid, research)[0]
        history = [message for message in events if message.get("from") == "buyer" and message.get("term_sheets")]
        offer_cap = self._earned_cap(case, events, history, standard, sid, cap, research)
        if history:
            previous = history[-1]["term_sheets"][0]["terms"].get("unit_price", state["target"])
            remaining = max(1, min(5, case.get("round_limit", 10) - 1 - state["turn"]))
            planned_price = float(previous) + (state["target"] - float(previous)) / remaining
            planned_price = min(state["target"], planned_price)
        else:
            planned_price = state["target"] * 0.96
        template = state["terms"] or {}
        primary = self._optimize_terms(
            case, complete_offer(case, {**template, "unit_price": max(0.01, planned_price)}),
            standard, sid, research,
        )
        return self._packages(case, primary, standard, sid, offer_cap, research)

    def decide(self, case, threads, research, writer):
        live = live_threads(threads)
        if not live:
            raise ValueError("cannot decide after all supplier threads have ended")
        states = {sid: self._state(case, sid, threads[sid], research) for sid in live}
        caps = {
            sid: self.batna(case, {other: events for other, events in threads.items() if other != sid}, sid, research)[0]
            for sid in live
        }

        ready = []
        for sid, state in states.items():
            accepted_offer = state["status"] == "agreed"
            if (state["valid"] and state["sheet_id"] and state["cost"] <= caps[sid] + 0.01
                    and (accepted_offer or state["cost"] <= self.acceptance_threshold(
                        case, threads[sid], state, caps[sid]
                    ) + 0.01)):
                ready.append((state["cost"], sid, state["sheet_id"]))
        deferred = None
        if ready:
            best_cost, best_sid, offer_id = min(ready)
            # A good standing quote is a real alternative, but do not close while a
            # live supplier has a materially better, BATNA-safe target and time to answer.
            opportunities = []
            if (moves_left(case, threads[best_sid]) > 0
                    and states[best_sid]["status"] != "final_offer"):
                opportunities = sorted(
                    (states[sid]["target_cost"], sid) for sid in live
                    if sid != best_sid and moves_left(case, threads[sid]) > 0
                    and states[sid]["status"] != "final_offer"
                    and states[sid]["target_cost"] < best_cost - max(0.01, abs(best_cost) * 0.02)
                )
            if opportunities:
                _, other_sid = opportunities[0]
                candidate_packages = self.offer_packages(case, threads, other_sid, research)
                if candidate_packages:
                    deferred = (other_sid, candidate_packages)
            if deferred is None:
                return {"supplier_id": best_sid,
                        "message": {"action": {"type": "accept", "term_sheet_id": offer_id}}}

        writable = [sid for sid in live if moves_left(case, threads[sid]) > 0
                    and states[sid]["status"] not in {"final_offer", "agreed"}]
        if not writable:
            return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}

        # Work the best priced supplier first, then try the remaining open suppliers if its
        # discrete terms cannot produce any BATNA-safe offer.
        quoted = [sid for sid in writable if states[sid]["valid"]]
        offer_order = sorted(quoted, key=lambda item: (states[item]["cost"], item))
        offer_order += sorted(
            (sid for sid in writable if sid not in quoted),
            key=lambda item: (states[item]["target_cost"], item),
        )
        sid, packages = deferred if deferred is not None else (None, [])
        if deferred is None:
            for candidate_sid in offer_order:
                candidate_packages = self.offer_packages(case, threads, candidate_sid, research)
                if candidate_packages:
                    sid, packages = candidate_sid, candidate_packages
                    break
        if not packages:
            return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}
        evidence_line, refs = self.researcher.opening_evidence(case, research)
        labels = {
            "payment_days": "earlier payment",
            "contract_months": "a longer commitment",
            "volume_per_year": "a larger annual volume",
            "lead_time_days": "a longer lead time",
            "ppm_commitment": "an adjusted quality commitment",
            "chargeback_eur_per_complaint": "a lower chargeback amount",
        }
        trade_descriptions = []
        for package in packages[1:]:
            for field, label in labels.items():
                if package.get(field) != packages[0].get(field) and label not in trade_descriptions:
                    trade_descriptions.append(label)
        draft = writer.draft(case, latest(threads[sid]), evidence_line, trade_descriptions)
        # Verified evidence is inserted by code; the language model is not allowed to alter it.
        body = evidence_line + "\n\n" + draft
        return {
            "supplier_id": sid,
            "message": {
                "subject": f"Re: {case['title']}"[:300],
                "body": body[:8000],
                "term_sheets": [{"terms": package} for package in packages],
                "refs": refs[:20],
            },
        }
        "payment_days": buyer["reference_payment_days"],
        "lead_time_days": buyer["need_lead_time_days"],
        "incoterm": min(freight, key=freight.get),
    }
    result = {}
    for field in case["negotiable"]:
        value = (offer or {}).get(field, defaults.get(field))
        if value is None:
            options = case.get("term_options", {}).get(field, [])
            value = options[0] if options else None
        value = snap(case, field, value)
        result[field] = round(value, 2) if field == "unit_price" and value is not None else value
    return result


def cost_parts(case, offer, supplier_standard=None, supplier=None):
    buyer = case["buyer"]
    terms = closing_terms(case, offer, supplier_standard)
    if terms.get("unit_price") is None:
        raise ValueError("a priced term sheet is required")
    years = _years(case, terms)
    committed = terms["volume_per_year"] * years
    need = buyer["need_per_year"]
    covered = min(terms["volume_per_year"], need) * years
    old_price_qty = _units_at_old_price(case, terms, years)
    new_price_qty = committed - old_price_qty
    spend = old_price_qty * (buyer.get("current_unit_price") or terms["unit_price"])
    spend += new_price_qty * terms["unit_price"]

    shortfall_qty = max(0.0, need * buyer["horizon_years"] - covered)
    shortfall = shortfall_qty * buyer["fallback_unit_price"]
    freight = buyer["freight_eur_per_unit"][terms["incoterm"]] * committed
    defect_exposure = buyer.get("cost_per_defect", 0) - min(
        terms.get("chargeback_eur_per_complaint") or 0, buyer.get("cost_per_defect", 0)
    )
    quality = committed * (terms.get("ppm_commitment") or 0) / 1_000_000 * defect_exposure

    index_cost = index_risk = 0.0
    clause = terms.get("index_clause")
    if clause:
        change = buyer.get("index_paths", {}).get(clause["series"], 0.0)
        over_band = max(0.0, abs(change) - clause["deadband_pct"] / 100)
        index_cost = new_price_qty * terms["unit_price"] * clause["material_share"] * over_band
        index_cost *= math.copysign(1, change)
        index_risk = (new_price_qty * terms["unit_price"] * clause["material_share"]
                      * buyer.get("index_risk_pct", 0) / 100)

    components = {
        "purchase": spend,
        "uncovered_need": shortfall,
        "fallback_uncertainty": shortfall * buyer.get("fallback_risk_pct", 0) / 100,
        "cash_timing": spend * buyer["interest_rate"]
        * (buyer["reference_payment_days"] - terms["payment_days"]) / 360,
        "freight": freight,
        "late_delivery": buyer.get("late_cost_per_day", 0)
        * max(0, terms["lead_time_days"] - buyer["need_lead_time_days"]),
        "quality": quality,
        "tooling": terms.get("tooling_eur") or 0.0,
        "index_movement": index_cost,
        "index_variance": index_risk,
        "supplier_health": _relationship_penalty(case, terms, supplier),
    }
    return components


def total_cost(case, offer, supplier_standard=None, supplier=None):
    if closing_terms(case, offer, supplier_standard).get("unit_price") is None:
        return math.inf
    return round(sum(cost_parts(case, offer, supplier_standard, supplier).values()), 2)
